	@Test
	void preexistingInterruptClosesWithoutEnteringSource() throws Exception {
		for (Operation operation : Operation.values()) {
			CloseOnlyIteration source = new CloseOnlyIteration(operation);
			try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(60_000);
					DeadlineIteration timed = new DeadlineIteration(source, deadline);
					ExecutorService executor = Executors.newSingleThreadExecutor()) {
				Future<Boolean> call = executor.submit(() -> {
					Thread.currentThread().interrupt();
					if (operation == Operation.HAS_NEXT) {
						assertFalse(timed.hasNext());
					} else if (operation == Operation.NEXT) {
						assertThrows(NoSuchElementException.class, timed::next);
					} else {
						assertThrows(IllegalStateException.class, timed::remove);
					}
					return Thread.currentThread().isInterrupted();
				});
				assertTrue(call.get(5, TimeUnit.SECONDS));
				assertEquals(1, source.entered.getCount());
				assertEquals(1, source.closeCalls.get());
			}
		}
	}

	@Test
	void timedOutExhaustionDoesNotWaitForBlockedCleanup() throws Exception {
		for (Operation operation : Operation.values()) {
			CloseOnlyIteration source = new CloseOnlyIteration(operation);
			source.available = false;
			if (operation == Operation.NEXT) {
				source.operationFailure = new NoSuchElementException("source exhausted during cancellation");
			} else if (operation == Operation.REMOVE) {
				source.operationFailure = new IllegalStateException("source closed during cancellation");
			}
			source.closeGate = new CountDownLatch(1);
			try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(60_000);
					ExecutorService executor = Executors.newSingleThreadExecutor()) {
				DeadlineIteration timed = new DeadlineIteration(source, deadline);
				try {
					Future<?> call = executor.submit(() -> operation.invoke(timed));
					assertTrue(source.entered.await(5, TimeUnit.SECONDS));
					timed.interrupt();
					assertTrue(source.released.await(2, TimeUnit.SECONDS));
					ExecutionException failure = assertThrows(ExecutionException.class,
							() -> call.get(2, TimeUnit.SECONDS),
							"the timeout must be observable while asynchronous cleanup remains blocked");
					assertSame(timed.timeout, failure.getCause());
					assertEquals(1, source.closeGate.getCount(), "cleanup must still be gated when the caller returns");
					assertFalse(timed.isClosed(), "timeout cleanup must leave explicit close able to await completion");
					CountDownLatch closerEntered = new CountDownLatch(1);
					Future<?> close = executor.submit(() -> {
						closerEntered.countDown();
						timed.close();
					});
					assertTrue(closerEntered.await(5, TimeUnit.SECONDS));
					assertThrows(TimeoutException.class, () -> close.get(250, TimeUnit.MILLISECONDS),
							"explicit close must still wait for source cleanup");
					source.closeGate.countDown();
					close.get(5, TimeUnit.SECONDS);
				} finally {
					source.released.countDown();
					source.closeGate.countDown();
					timed.close();
				}
				assertEquals(1, source.closeCalls.get());
			}
		}
	}

	private void assertDeadlineCancellationReleasesCloseOnlyWait(Operation operation) throws Exception {
		for (boolean nested : new boolean[] { false, true }) {
			CloseOnlyIteration source = new CloseOnlyIteration(operation);
			CloseableIteration<Integer> delegate = source;
			if (nested) {
				delegate = new IterationWrapper<>(new IterationWrapper<>(source));
			}
			try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(60_000)) {
				DeadlineIteration timed = new DeadlineIteration(delegate, deadline);
				ExecutorService executor = Executors.newSingleThreadExecutor();
				try {
					Future<?> call = executor.submit(() -> operation.invoke(timed));
					assertTrue(source.entered.await(5, TimeUnit.SECONDS));
					timed.interrupt();
					assertTrue(source.released.await(2, TimeUnit.SECONDS),
							"timeout must close a source whose active call can only return after close");
					ExecutionException failure = assertThrows(ExecutionException.class,
							() -> call.get(5, TimeUnit.SECONDS));
					assertSame(timed.timeout, failure.getCause());
					timed.close();
					assertEquals(1, source.closeCalls.get());
				} finally {
					source.released.countDown();
					executor.shutdownNow();
					assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
					timed.close();
				}
			}
		}
	}

	private enum Operation {
		HAS_NEXT,
		NEXT,
		REMOVE;

		void invoke(CloseableIteration<Integer> iteration) {
			switch (this) {
			case HAS_NEXT -> iteration.hasNext();
			case NEXT -> iteration.next();
			case REMOVE -> iteration.remove();
			}
		}
	}

	private static final class DeadlineIteration extends TimeLimitIteration<Integer> {
		private final IllegalStateException timeout = new IllegalStateException("deadline expired");
		private QueryExecutionDeadline closeDeadline;

		private DeadlineIteration(CloseableIteration<Integer> source, QueryExecutionDeadline deadline) {
			super(source, deadline);
			registerDeadline();
		}

		@Override
		protected void throwInterruptedException() {
			throw timeout;
		}

		@Override
		protected void handleClose() {
			closeDeadline = QueryExecutionDeadline.current();
			super.handleClose();
		}
	}

	private static final class CloseOnlyIteration implements CloseableIteration<Integer> {
		private final Operation operation;
		private final CountDownLatch entered = new CountDownLatch(1);
		private final CountDownLatch released = new CountDownLatch(1);
		private final AtomicInteger closeCalls = new AtomicInteger();
		private RuntimeException operationFailure;
		private RuntimeException closeFailure;
		private QueryExecutionDeadline closeDeadline;
		private boolean available = true;
		private CountDownLatch closeGate;

		private CloseOnlyIteration(Operation operation) {
			this.operation = operation;
		}

		private void waitForClose(Operation call) {
			if (operation != call) {
				return;
			}
			entered.countDown();
			boolean interrupted = false;
			while (true) {
				try {
					released.await();
					break;
				} catch (InterruptedException e) {
					interrupted = true;
				}
			}
			if (interrupted) {
				Thread.currentThread().interrupt();
			}
			if (operationFailure != null) {
				throw operationFailure;
			}
		}

		@Override
		public boolean hasNext() {
			waitForClose(Operation.HAS_NEXT);
			return available;
		}

		@Override
		public Integer next() {
			waitForClose(Operation.NEXT);
			return 1;
		}

		@Override
		public void remove() {
			waitForClose(Operation.REMOVE);
		}

		@Override
		public void close() {
			closeDeadline = QueryExecutionDeadline.current();
			closeCalls.incrementAndGet();
			released.countDown();
			if (closeGate != null) {
				boolean interrupted = false;
				while (true) {
					try {
						closeGate.await();
						break;
					} catch (InterruptedException e) {
						interrupted = true;
					}
				}
				if (interrupted) {
					Thread.currentThread().interrupt();
				}
			}
			if (closeFailure != null) {
				throw closeFailure;
			}
		}
	}
